from abc import abstractproperty
import inspect


class staticproperty(property):
    """A modification of the built-in property that makes it static. Works only as a decorator:
    ::
        class MyClass(object):
            __metaclass__ = ABCMeta

            @staticproperty
            def my_property():
                return 'foo'

        print MyClass.my_property
        print MyClass().my_property
        # both print 'foo'
    """
    def __get__(self, cls, owner):
        return staticmethod(self.fget).__get__(None, owner)()


class classproperty(property):
    """A modification of the built-in property that makes it a class property. Works only as a decorator:
    ::
        class MyClass(object):
            @classproperty
            def my_property(cls):
                return 'foo in ' + cls.__name__

        print MyClass.my_property
        print MyClass().my_property
        # both print 'foo in MyClass'
    """
    def __get__(self, cls, owner):
        return classmethod(self.fget).__get__(None, owner)()


class abstractstaticproperty(abstractproperty):
    """A modification of abc.abstractproperty that makes it static. Works only as a decorator:
    ::
        class MyAbstractClass(object):
            __metaclass__ = ABCMeta

            @abstractstaticproperty
            def my_property():
                '''Inheritors should implement this'''

        class MyClass1(MyAbstractClass):
            @staticproperty
            def my_property():
                return 'foo'

        class MyClass2(MyAbstractClass):
            my_property = 'foo'

        MyAbstractClass()
        MyAbstractClass.my_property
        # both raise a TypeError

        print MyClass1.my_property
        print MyClass1().my_property
        print MyClass2.my_property
        print MyClass2().my_property
        # all four print 'foo'
    """
    def __get__(self, cls, owner):
        if _is_system_call():
            # We cannot always raise TypeError because it would sometimes prevent the class itself from being created
            # or break inspect.getmembers() calls.
            # For creating classes, the problem occurs when a class inherits some abstract properties and does not override them.
            # ABCMeta will then try to copy the properties from the base class and will fail if TypeError is raised.
            # Returning self in this case is consistent with how abc.abstractproperty works and also solves the problem of
            # recognizing the properties as abstract.
            return self
        else:
            raise TypeError("Can't access an abstract static property {} of class {}".format(self.fget.__name__, owner.__name__))


class abstractclassproperty(abstractproperty):
    """A modification of abc.abstractproperty that makes it a class property. Works only as a decorator:
    ::
        class MyAbstractClass(object):
            __metaclass__ = ABCMeta

            @abstractclassproperty
            def my_property(cls):
                '''Inheritors should implement this'''

        class MyClass1(MyAbstractClass):
            @classproperty
            def my_property(cls):
                return 'foo in ' + cls.__name__

        class MyClass2(MyAbstractClass):
            my_property = 'foo'

        MyAbstractClass()
        MyAbstractClass.my_property
        # both raise a TypeError

        print MyClass1.my_property
        print MyClass1().my_property
        # both print 'foo in MyClass1'

        print MyClass2.my_property
        print MyClass2().my_property
        # both print 'foo'
    """
    def __get__(self, cls, owner):
        if _is_system_call():
            # We cannot always raise TypeError because it would sometimes prevent the class itself from being created
            # or break inspect.getmembers() calls.
            # For creating classes, the problem occurs when a class inherits some abstract properties and does not override them.
            # ABCMeta will then try to copy the properties from the base class and will fail if TypeError is raised.
            # Returning self in this case is consistent with how abc.abstractproperty works and also solves the problem of
            # recognizing the properties as abstract.
            return self
        else:
            raise TypeError("Can't access an abstract class property {} of class {}".format(self.fget.__name__, owner.__name__))


def _is_system_call():
    filename, function_name = _get_caller(depth=3)
    return (filename.endswith('abc.py') and function_name == '__new__') \
        or (filename.endswith('inspect.py') and function_name == 'getmembers')


def _get_caller(depth=2):
    frame = inspect.stack()[depth][0]
    try:
        return frame.f_code.co_filename, frame.f_code.co_name
    finally:
        del frame  # this is done to avoid creating a circular reference
